function(container, apiUrl, tables) {
  let salesChart = null;
  let weatherChart = null;

  // データ更新関数
  async function updateDashboard() {
    try {
      container.querySelector("#error-message").classList.add("hidden");

      const selectedStore = container.querySelector("#store-select").value;
      const selectedPeriod = parseInt(container.querySelector("#period-select").value);

      // 各テーブルからデータを取得
      const salesData = await window.aivicApi.list(3) || []; // 売上実績データ
      const forecastData = await window.aivicApi.list(9) || []; // 需要予測結果
      const orderData = await window.aivicApi.list(10) || []; // 発注データ
      const productData = await window.aivicApi.list(2) || []; // 商品マスタ
      const weatherData = await window.aivicApi.list(4) || []; // 天候データ
      const eventData = await window.aivicApi.list(5) || []; // イベントデータ

      // 期間フィルタリング
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - selectedPeriod);

      const filteredSales = salesData.filter(s => {
        if (selectedStore && s.店舗ID !== selectedStore) return false;
        return new Date(s.売上日) >= cutoffDate;
      });

      // KPI計算
      updateKPIs(filteredSales, forecastData, orderData);

      // グラフ更新
      updateSalesTrendChart(filteredSales);
      updateWeatherChart(weatherData, filteredSales);

      // ランキング更新
      updateProductRanking(filteredSales, productData);

      // ステータス更新
      updateOrderStatus(orderData);

      // アラート更新
      updateInventoryAlerts(filteredSales, productData);

      // イベント更新
      updateEventFactors(eventData);

    } catch (error) {
      console.error("Dashboard update error:", error);
      container.querySelector("#error-message").classList.remove("hidden");
    }
  }

  // KPI更新
  function updateKPIs(salesData, forecastData, orderData) {
    // 売上実績
    const totalSales = salesData.reduce((sum, s) => sum + (s.売上金額 || 0), 0);
    container.querySelector("#kpi-sales").textContent = `¥${totalSales.toLocaleString()}`;

    // 需要予測精度（MAPE計算）
    const accuracyData = forecastData.filter(f => f.実績数量 && f.予測数量);
    let avgAccuracy = 0;
    if (accuracyData.length > 0) {
      const mape = accuracyData.reduce((sum, f) => {
        return sum + Math.abs((f.実績数量 - f.予測数量) / f.実績数量);
      }, 0) / accuracyData.length;
      avgAccuracy = Math.max(0, 100 - (mape * 100));
    }
    container.querySelector("#kpi-accuracy").textContent = `${avgAccuracy.toFixed(1)}%`;

    // 発注件数
    const orderCount = orderData.length;
    container.querySelector("#kpi-orders").textContent = `${orderCount}件`;

    // 在庫アラート（仮の計算）
    const alertCount = Math.floor(salesData.length * 0.1);
    container.querySelector("#kpi-alerts").textContent = `${alertCount}件`;
  }

  // 売上トレンドグラフ
  function updateSalesTrendChart(salesData) {
    const ctx = container.querySelector("#sales-trend-chart").getContext("2d");

    // 日別集計
    const dailySales = {};
    salesData.forEach(s => {
      const date = s.売上日?.slice(0, 10) || new Date().toISOString().slice(0, 10);
      dailySales[date] = (dailySales[date] || 0) + (s.売上金額 || 0);
    });

    const sortedDates = Object.keys(dailySales).sort();
    const labels = sortedDates.map(d => d.slice(5)); // MM-DD形式
    const data = sortedDates.map(d => dailySales[d]);

    if (salesChart) {
      salesChart.destroy();
    }

    salesChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 天候影響分析チャート
  function updateWeatherChart(weatherData, salesData) {
    const ctx = container.querySelector("#weather-chart").getContext("2d");

    // 気温別売上集計
    const tempSales = {};
    salesData.forEach(s => {
      const temp = s.気温 || 20;
      const tempRange = Math.floor(temp / 5) * 5; // 5度刻み
      tempSales[tempRange] = (tempSales[tempRange] || 0) + (s.売上金額 || 0);
    });

    const temps = Object.keys(tempSales).sort((a, b) => a - b);
    const labels = temps.map(t => `${t}°C~`);
    const data = temps.map(t => tempSales[t]);

    if (weatherChart) {
      weatherChart.destroy();
    }

    weatherChart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          backgroundColor: '#7cb342'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function updateProductRanking(salesData, productData) {
    const productSales = {};
    salesData.forEach(s => {
      productSales[s.商品ID] = (productSales[s.商品ID] || 0) + (s.売上金額 || 0);
    });

    const ranking = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    const html = ranking.map(([productId, sales], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product?.商品名 || `商品${productId}`;
      return `
        <div class="ranking-item">
          <span class="rank">${index + 1}</span>
          <span class="product-name">${productName}</span>
          <span class="sales-amount">¥${sales.toLocaleString()}</span>
        </div>
      `;
    }).join("");

    container.querySelector("#product-ranking").innerHTML = html || '<div class="ranking-item"><span class="product-name">データがありません</span></div>';
  }

  // 発注状況ステータス
  function updateOrderStatus(orderData) {
    const statusCounts = {
      pending: 0,
      ordered: 0,
      received: 0
    };

    orderData.forEach(o => {
      const status = o.発注ステータス || '未発注';
      if (status.includes('未発注')) statusCounts.pending++;
      else if (status.includes('発注済')) statusCounts.ordered++;
      else if (status.includes('納品済')) statusCounts.received++;
    });

    container.querySelector("#status-pending").textContent = statusCounts.pending;
    container.querySelector("#status-ordered").textContent = statusCounts.ordered;
    container.querySelector("#status-received").textContent = statusCounts.received;
  }

  // 在庫アラート
  function updateInventoryAlerts(salesData, productData) {
    const alerts = [];

    // 売上の多い商品で在庫切れフラグがある場合をアラートとする
    const productSales = {};
    salesData.forEach(s => {
      if (s.在庫切れフラグ) {
        productSales[s.商品ID] = (productSales[s.商品ID] || 0) + (s.売上金額 || 0);
      }
    });

    Object.entries(productSales).slice(0, 5).forEach(([productId, sales]) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product?.商品名 || `商品${productId}`;
      alerts.push({
        level: 'warning',
        message: `${productName} - 在庫不足が発生しています`
      });
    });

    const html = alerts.length > 0 ? alerts.map(alert => `
      <div class="alert-item">
        <span class="alert-level ${alert.level}">${alert.level === 'warning' ? '警告' : '注意'}</span>
        <span class="alert-message">${alert.message}</span>
      </div>
    `).join("") : '<div class="alert-item"><span class="alert-message">現在アラートはありません</span></div>';

    container.querySelector("#inventory-alerts").innerHTML = html;
  }

  // イベント・季節要因
  function updateEventFactors(eventData) {
    const today = new Date();
    const futureEvents = eventData
      .filter(e => new Date(e.開始日時) >= today)
      .sort((a, b) => new Date(a.開始日時) - new Date(b.開始日時))
      .slice(0, 5);

    const html = futureEvents.length > 0 ? futureEvents.map(event => {
      const date = new Date(event.開始日時);
      const dateStr = `${date.getMonth() + 1}/${date.getDate()}`;
      return `
        <div class="event-item">
          <span class="event-date">${dateStr}</span>
          <span class="event-name">${event.イベント名 || 'イベント'}</span>
          <span class="event-impact">影響度: ${event.影響度 || '中'}</span>
        </div>
      `;
    }).join("") : '<div class="event-item"><span class="event-name">予定されているイベントはありません</span></div>';

    container.querySelector("#event-factors").innerHTML = html;
  }

  // 店舗選択肢を設定
  function setupStoreOptions() {
    const storeData = tables[1]?.records || []; // 店舗マスタ
    const storeSelect = container.querySelector("#store-select");

    storeData.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement("option");
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // イベントリスナー設定
  container.querySelector("#btn-refresh").addEventListener("click", updateDashboard);
  container.querySelector("#store-select").addEventListener("change", updateDashboard);
  container.querySelector("#period-select").addEventListener("change", updateDashboard);
  container.querySelector("#btn-retry").addEventListener("click", updateDashboard);

  // 初期化
  setupStoreOptions();
  updateDashboard();
}
